package com.pratik.imagetap;
import android.accessibilityservice.AccessibilityService;import android.accessibilityservice.GestureDescription;import android.content.*;import android.os.*;import android.util.DisplayMetrics;import android.view.*;import android.widget.*;import java.lang.reflect.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w412dp-h892dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class TapDeliveryTest {
 public static class RecordingService extends TapService {int sent;boolean accepted=true,fail;GestureDescription gesture;AccessibilityService.GestureResultCallback callback;@Override protected boolean sendTapGesture(GestureDescription g,AccessibilityService.GestureResultCallback cb){sent++;if(fail)throw new IllegalStateException("service disconnected");gesture=g;callback=cb;return accepted;}}
 RecordingService service;SharedPreferences prefs;DisplayMetrics dm;org.robolectric.android.controller.ServiceController<RecordingService> ctl;
 @Before public void setup()throws Exception{ctl=Robolectric.buildService(RecordingService.class).create();service=ctl.get();prefs=service.getSharedPreferences("config",0);prefs.edit().putBoolean("tap",true).putBoolean("confirm",false).putInt("similarity",96).commit();WindowManager wm=(WindowManager)service.getSystemService(Context.WINDOW_SERVICE);set("wm",wm);set("prefs",prefs);invoke("showPanel");set("running",true);set("latched",new boolean[3]);set("missing",new int[3]);dm=new DisplayMetrics();wm.getDefaultDisplay().getRealMetrics(dm);SystemClock.sleep(1000);}
 @After public void close(){service.stopSession("test");ctl.destroy();}
 void hit(int target,long stamp)throws Exception{VisionMatcher.Hit[] hits=new VisionMatcher.Hit[3];boolean[] checked=new boolean[3];hits[target]=new VisionMatcher.Hit(300+target*60,400,24,24,99,96);checked[target]=true;Method f=TapService.class.getDeclaredMethod("finish",VisionMatcher.Hit[].class,boolean[].class,int.class,int.class,int.class,double.class,String.class,boolean.class,String.class,long.class,boolean.class);f.setAccessible(true);f.invoke(service,hits,checked,dm.widthPixels,dm.heightPixels,(Integer)get("generation"),255*(100-96)/100.0,"[]",true,"",stamp,false);}
 String feedback()throws Exception{return ((TextView)get("tapFeedback")).getText().toString();}
 @Test public void detectionDispatches100msAndCompletionReportsAndroidOnly()throws Exception{hit(0,SystemClock.uptimeMillis());assertEquals(1,service.sent);assertEquals(100,service.gesture.getStroke(0).getDuration());assertTrue((Boolean)get("gesturePending"));service.callback.onCompleted(service.gesture);assertFalse((Boolean)get("gesturePending"));assertEquals(1L,get("taps"));assertTrue(feedback().contains("Android completed"));assertEquals("1 action",((TextView)get("tapBadge")).getText().toString());}
 @Test public void competingTargetsConfirmIndependentlyAcrossDistinctFrames()throws Exception{prefs.edit().putBoolean("confirm",true).commit();long a=SystemClock.uptimeMillis();hit(0,a);hit(1,a);assertEquals(0,service.sent);assertTrue(feedback().contains("confirming 1/2"));SystemClock.sleep(500);hit(0,SystemClock.uptimeMillis());assertEquals(1,service.sent);}
 @Test public void sameFrameCannotConfirmItself()throws Exception{prefs.edit().putBoolean("confirm",true).commit();long a=SystemClock.uptimeMillis();hit(0,a);hit(0,a);assertEquals(0,service.sent);SystemClock.sleep(500);hit(0,SystemClock.uptimeMillis());assertEquals(1,service.sent);}
 @Test public void alreadyTappedTargetDoesNotResetAnotherConfirmation()throws Exception{prefs.edit().putBoolean("confirm",true).putBoolean("repeat",false).commit();set("latched",new boolean[]{true,false,false});long a=SystemClock.uptimeMillis();hit(1,a);hit(0,a);assertEquals(0,service.sent);SystemClock.sleep(500);hit(1,SystemClock.uptimeMillis());assertEquals(1,service.sent);}
 @Test public void previewAndStaleFramesNeverDispatch()throws Exception{prefs.edit().putBoolean("tap",false).commit();hit(0,SystemClock.uptimeMillis());assertEquals(0,service.sent);assertEquals("Preview · actions off",feedback());prefs.edit().putBoolean("tap",true).commit();long old=SystemClock.uptimeMillis();SystemClock.sleep(2100);hit(0,old);assertEquals(0,service.sent);assertTrue(feedback().contains("Old frame"));}
 @Test public void cancelledAndRejectedGesturesCanRetry()throws Exception{long t=SystemClock.uptimeMillis();hit(0,t);service.callback.onCancelled(service.gesture);assertFalse((Boolean)get("gesturePending"));assertTrue(feedback().contains("cancelled"));SystemClock.sleep(500);service.accepted=false;hit(0,SystemClock.uptimeMillis());assertEquals(2,service.sent);assertFalse((Boolean)get("gesturePending"));assertTrue(feedback().contains("rejected"));SystemClock.sleep(500);service.accepted=true;hit(0,SystemClock.uptimeMillis());assertEquals(3,service.sent);}
 @Test public void durationClampsAndExceptionsDoNotLatchPending()throws Exception{prefs.edit().putInt("pressMs",999).commit();service.fail=true;hit(0,SystemClock.uptimeMillis());assertFalse((Boolean)get("gesturePending"));assertTrue(feedback().contains("unavailable"));service.fail=false;SystemClock.sleep(500);hit(0,SystemClock.uptimeMillis());assertEquals(250,service.gesture.getStroke(0).getDuration());assertEquals(40,TapTiming.press(-1));}
 @Test public void onlyOneAcceptedGesturePerFrame()throws Exception{long t=SystemClock.uptimeMillis();hit(0,t);service.callback.onCompleted(service.gesture);hit(1,t);assertEquals(1,service.sent);assertTrue(feedback().contains("Already sent"));}
 @Test public void pauseRecordsCompletedGestureWithoutStartingAnother()throws Exception{hit(0,SystemClock.uptimeMillis());service.togglePause();service.callback.onCompleted(service.gesture);assertEquals(1L,get("taps"));assertEquals(1,service.sent);assertFalse((Boolean)get("gesturePending"));assertTrue(feedback().contains("Paused"));}
 @Test public void slowDiscoveryQueuesFreshVerificationInsteadOfDiscardingIt()throws Exception{prefs.edit().putBoolean("confirm",true).commit();long old=SystemClock.uptimeMillis();SystemClock.sleep(4500);hit(0,old);assertEquals(0,service.sent);assertNotNull(get("freshCheck"));assertTrue(feedback().contains("rechecking candidates"));hit(0,SystemClock.uptimeMillis());assertEquals(1,service.sent);}
 @Test public void pauseDiscardsQueuedFreshVerification()throws Exception{long old=SystemClock.uptimeMillis();SystemClock.sleep(2100);hit(0,old);assertNotNull(get("freshCheck"));service.togglePause();assertNull(get("freshCheck"));hit(0,SystemClock.uptimeMillis());assertEquals(0,service.sent);}
 @Test public void stopDiscardsQueuedFreshVerification()throws Exception{long old=SystemClock.uptimeMillis();SystemClock.sleep(2100);hit(0,old);service.stopSession("Stop");assertNull(get("freshCheck"));hit(0,SystemClock.uptimeMillis());assertEquals(0,service.sent);}
 @Test public void changedSimilarityInvalidatesOldDiscovery()throws Exception{long old=SystemClock.uptimeMillis();SystemClock.sleep(2100);hit(0,old);prefs.edit().putInt("similarity",100).commit();hit(0,SystemClock.uptimeMillis());assertEquals(0,service.sent);assertNull(get("freshCheck"));}
 @Test public void staticContentCanActOnDistinctFreshFrames()throws Exception{long stamp=SystemClock.uptimeMillis();hit(0,stamp);service.callback.onCompleted(service.gesture);SystemClock.sleep(500);hit(0,SystemClock.uptimeMillis());assertEquals(2,service.sent);}
 @Test public void freshCheckDoesNotWaitForTenSecondPulse()throws Exception{prefs.edit().putInt("pulseMs",10000).commit();long old=SystemClock.uptimeMillis();SystemClock.sleep(2100);hit(0,old);set("lastCapture",SystemClock.elapsedRealtime());Method next=TapService.class.getDeclaredMethod("next",int.class);next.setAccessible(true);next.invoke(service,(Integer)get("generation"));String message=((TextView)get("pulseLabel")).getText().toString();assertTrue(message,message.contains("0.4 s"));}
 Object get(String n)throws Exception{Field f=TapService.class.getDeclaredField(n);f.setAccessible(true);return f.get(service);}void set(String n,Object x)throws Exception{Field f=TapService.class.getDeclaredField(n);f.setAccessible(true);f.set(service,x);}void invoke(String n)throws Exception{Method m=TapService.class.getDeclaredMethod(n);m.setAccessible(true);m.invoke(service);}
}
